SourceCode.Declaration:
/// <summary>
/// Wall-to-wall counts, one row each, kept as history. While a row is Building, Counting or Posting
/// its warehouse is frozen: the handheld's movements and D365FO's stock postings there are refused,
/// except the posting of the count's own journal. Started, cancelled and posted from Count
/// warehouses (HSMobileOpsCountWallToWall).
/// </summary>
public class HSMobileOpsWarehouseFreeze extends common
{
}

Method.Source:
public boolean isActive()
{
    return this.RecId
        && (this.Status == HSMobileOpsFreezeStatus::Building
         || this.Status == HSMobileOpsFreezeStatus::Counting
         || this.Status == HSMobileOpsFreezeStatus::Posting);
}

/// <summary>The warehouse's wall-to-wall count while it is frozen, else an empty buffer.</summary>
public static HSMobileOpsWarehouseFreeze findActive(InventLocationId _warehouse, boolean _forUpdate = false)
{
    HSMobileOpsWarehouseFreeze freeze;

    if (!_warehouse)
    {
        return freeze;
    }
    freeze.selectForUpdate(_forUpdate);
    select firstOnly freeze
        order by StartedUtc desc
        where freeze.InventLocationId == _warehouse
           && (freeze.Status == HSMobileOpsFreezeStatus::Building
            || freeze.Status == HSMobileOpsFreezeStatus::Counting
            || freeze.Status == HSMobileOpsFreezeStatus::Posting);
    return freeze;
}

public static HSMobileOpsWarehouseFreeze findByJournal(InventJournalId _journalId, boolean _forUpdate = false)
{
    HSMobileOpsWarehouseFreeze freeze;

    if (!_journalId)
    {
        return freeze;
    }
    freeze.selectForUpdate(_forUpdate);
    select firstOnly freeze
        order by StartedUtc desc
        where freeze.JournalId == _journalId;
    return freeze;
}

/// <summary>
/// Why a stock movement in this warehouse is refused, or empty when it is not frozen. The one
/// text every refusal uses, on the handheld and in D365FO alike.
/// </summary>
public static str frozenMessage(InventLocationId _warehouse)
{
    HSMobileOpsWarehouseFreeze freeze = HSMobileOpsWarehouseFreeze::findActive(_warehouse);
    utcdatetime                local;

    if (!freeze.RecId)
    {
        return '';
    }
    // The company's time, readably: a handheld's call runs as the service user, whose own
    // zone gave UTC as "2026-11-08T02:49:44" (seen 8 Nov).
    local = DateTimeUtil::applyTimeZoneOffset(freeze.StartedUtc, DateTimeUtil::getCompanyTimeZone());
    return strFmt('Warehouse %1 is frozen for a wall-to-wall count (%2) since %3 %4. Stock cannot move there until the count is posted or cancelled.',
        _warehouse, freeze.JournalId ? freeze.JournalId : enum2Str(freeze.Status),
        date2Str(DateTimeUtil::date(local), 123, DateDay::Digits1or2, DateSeparator::Space, DateMonth::Short, DateSeparator::Space, DateYear::Digits4),
        strLTrim(time2StrHM(DateTimeUtil::time(local))));
}

/// <summary>
/// True when the warehouse is not frozen; else puts the reason in the infolog and answers false.
/// The wall-to-wall count's own journal is let through when given.
/// </summary>
public static boolean checkNotFrozen(InventLocationId _warehouse, InventJournalId _ownJournalId = '')
{
    HSMobileOpsWarehouseFreeze freeze = HSMobileOpsWarehouseFreeze::findActive(_warehouse);

    if (!freeze.RecId || (_ownJournalId && freeze.JournalId == _ownJournalId))
    {
        return true;
    }
    return checkFailed(HSMobileOpsWarehouseFreeze::frozenMessage(_warehouse));
}
